static const size_t kRawLen3 = 360; static const uint32_t kCrc3 = 0x6a005ad8u;
static const char kT3[] = "abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra abracadabra ";

int main() {
  // The application may unpack its PDFium and Tectonic resources at the same time. Exercise the first use of the
  // shared fixed-Huffman tables concurrently, before any other inflate call has initialized them.
  std::atomic<int> concurrentFails{0};
  vector<std::thread> inflaters;
  for (int i = 0; i < 16; i++) inflaters.emplace_back([&]() {
    string decoded;
    if (!inflateRaw(kZ3, sizeof kZ3, decoded) || decoded != string(kT3) ||
        crc32(reinterpret_cast<const uint8_t*>(decoded.data()), decoded.size()) != kCrc3) concurrentFails++;
  });
  for (auto& worker : inflaters) worker.join();
  string out;
  CHECK(concurrentFails == 0);
  // dynamic Huffman block (zlib level 9)
  CHECK(inflateRaw(kZ1, sizeof kZ1, out) && out.size() == kRawLen1 && crc32((const uint8_t*)out.data(), out.size()) == kCrc1);
  CHECK(out.rfind("The quick brown fox", 0) == 0);
  // stored blocks (zlib level 0)
  CHECK(inflateRaw(kZ2, sizeof kZ2, out) && out.size() == kRawLen2 && crc32((const uint8_t*)out.data(), out.size()) == kCrc2);
  // fixed Huffman block (Z_FIXED)
  CHECK(inflateRaw(kZ3, sizeof kZ3, out) && out.size() == kRawLen3 && out == string(kT3));
  // truncated / garbage input fails cleanly
  string err;
  CHECK(!inflateRaw(kZ1, sizeof kZ1 / 2, out, 0, &err) && !err.empty());
  uint8_t junk[] = {0xFF, 0xFF, 0xFF, 0xFF};
  CHECK(!inflateRaw(junk, sizeof junk, out));
  // the in-house encoder (fixed Huffman + LZ77) round-trips through the decoder, also for binary data
  std::mt19937 rng(11);
  string bin(200000, '\0');
  for (size_t i = 0; i < bin.size(); i++) bin[i] = char(i % 977 < 700 ? (i * 31) % 251 : rng() & 0xFF);
  string zl = zlibCompress(bin);
  CHECK(inflateZlib((const uint8_t*)zl.data(), zl.size(), out) && out == bin);
  // the blob container
  string blob = packBlob(8076, bin);
  uint32_t tag = 0, rawSize = 0;
  CHECK(blobInfo((const uint8_t*)blob.data(), blob.size(), &tag, &rawSize) && tag == 8076 && rawSize == bin.size());
  string raw;
  CHECK(unpackBlob((const uint8_t*)blob.data(), blob.size(), raw, &tag, &err) && raw == bin && tag == 8076);
  blob[blob.size() / 2] ^= 0x55;  // a flipped byte is caught (by the decoder or the checksum)
  CHECK(!unpackBlob((const uint8_t*)blob.data(), blob.size(), raw, &tag, &err));
  string empty = packBlob(1, "");
  CHECK(empty.size() == 20 && unpackBlob((const uint8_t*)empty.data(), empty.size(), raw) && raw.empty());
  if (fails) { std::cerr << fails << " check(s) failed\n"; return 1; }
  std::cout << "inflate_test: all checks passed\n";
  return 0;
}
